-- VFDA VA Quiz App - Card-first database changes (card mapping, scenario sources, must-ask questions only).
-- GENERATED by `npm run db:bundle` from supabase/migrations/. Edit those files, not this one.
-- Paste into the Supabase SQL Editor and run after invite-va.sql.
-- Runs in one transaction: if anything fails, nothing is changed.

begin;

-- ===== 20261102150000_card_first.sql =====

-- Card-first scenarios: the office's Trello card PDFs are the source of its
-- quizzes; the master bank is only the pattern.
--
-- Each card PDF is read once: its title, Trello color, text, and suggested
-- schedule day(s) and workflow (VFDA can change the mapping, or mark the card
-- "skip" when it has no process content). Office scenarios record the card
-- and the card's own words they came from.
--
-- The doctor answers only the 12 must-ask rules the cards don't cover and
-- accepts the VFDA standards with one checkbox. Card rules VFDA accepts no
-- longer wait for the doctor; edge-case questions and every other open gap
-- question are removed (answers already given stay).
--
-- Safe to run more than once.

-- Card mapping.
alter table public.office_documents add column if not exists card_title text not null default '';
alter table public.office_documents add column if not exists card_color text;
alter table public.office_documents drop constraint if exists office_documents_card_color_check;
alter table public.office_documents add constraint office_documents_card_color_check
  check (card_color is null or card_color in ('green', 'orange', 'yellow', 'gray', 'other'));
-- A card can feed more than one day (phone scripts: W2D1 and W2D2).
alter table public.office_documents add column if not exists schedule_days text[] not null default '{}';
alter table public.office_documents add column if not exists workflow text;
alter table public.office_documents add column if not exists skip boolean not null default false;
alter table public.office_documents add column if not exists tags text[] not null default '{}';
alter table public.office_documents add column if not exists mapped_by uuid references public.profiles (id) on delete set null;
alter table public.office_documents add column if not exists mapped_at timestamptz;

-- Where each office scenario came from.
alter table public.office_scenarios add column if not exists source_card text;
alter table public.office_scenarios add column if not exists source_quote text;
alter table public.office_scenarios add column if not exists source_document_id uuid
  references public.office_documents (id) on delete set null;

-- "Anything your cards don't cover uses VFDA standards."
alter table public.offices add column if not exists standards_accepted_at timestamptz;
alter table public.offices add column if not exists standards_accepted_by uuid references public.profiles (id) on delete set null;

-- Card rules VFDA accepted were waiting for the doctor's confirmation; that
-- screen is gone, so they count as accepted.
update public.office_rules set status = 'accepted'
  where source = 'card_import' and status = 'needs_doctor';

-- Only the 12 must-ask rules are still asked.
delete from public.gap_questions
  where answered_at is null
    and (rule_slot_key is null
         or rule_slot_key not in ('CONFIRM_RULE', 'NO_SHOW_RULE', 'SAME_DAY_CUTOFF', 'TEXT_RESPONSE_TIME',
                                  'CALLBACK_TIME', 'ESCALATION_CHANNEL', 'FOLLOWUP_INTERVAL', 'VA_AUTHORITY',
                                  'BILLING_AUTHORITY', 'PROHIBITED_PHRASES', 'ESCALATION_CONTACT', 'OFFICE_HOURS'));

commit;
